mod baseline;mod packet;mod verifier;mod sparse;
use hec_native_ic::{counted,fp::Fp,jac::Curve,poly::Poly,rng::Rng,instance::factor_base};
fn main(){counted::disable();let mut positives=0;let mut negatives=0;for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let fb=factor_base(&c);let base=c.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026113000^p);for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let expected=1+rng.below(ell-1);let target=c.mul(&d,expected);let rep=baseline::solve(&c,&d,&target,ell,sm,false);assert_eq!(rep.k,Some(expected));let cert=packet::take();assert_eq!(cert.k,expected);assert!(verifier::verify(&cert));positives+=1;
 let mut bad=cert.clone();bad.target=c.add(&bad.target,&d);assert!(!verifier::verify(&bad));negatives+=1;let mut bad=cert.clone();bad.d=c.add(&bad.d,&d);assert!(!verifier::verify(&bad));negatives+=1;let mut bad=cert.clone();bad.lambda=(bad.lambda+1)%ell;assert!(!verifier::verify(&bad));negatives+=1;let mut bad=cert.clone();bad.rows[0].coeff[0]=(bad.rows[0].coeff[0]+1)%ell;assert!(!verifier::verify(&bad));negatives+=1;let mut bad=cert.clone();bad.witness[0]=(bad.witness[0]+1)%ell;assert!(!verifier::verify(&bad));negatives+=1;let mut bad=cert.clone();bad.k=(bad.k+1)%ell;assert!(!verifier::verify(&bad));negatives+=1;let mut bad=cert.clone();let row=bad.rows.iter_mut().find(|r|matches!(r.kind,packet::Kind::Pencil{..})).unwrap();if let packet::Kind::Pencil{points,..}=&mut row.kind{points[0].1=(points[0].1+1)%p;}assert!(!verifier::verify(&bad));negatives+=1;
 println!("CERT\tp={p}\tsm={sm}\tcase={case}\tpacket={cert:?}");println!("PASS\tp={p}\tsm={sm}\tcase={case}\trows={}\twitness_len={}\tk={expected}\tmutations_rejected=7",cert.rows.len(),cert.witness.len());}}}assert_eq!((positives,negatives),(12,84));eprintln!("original_target_certificates=12 mutations_rejected=84 native_final_scalar_control=true native_action_check=true wholeprime_fixed_instance_order_external_premise=true independent_verification=false");}
